from html.parser import HTMLParser
class Validator(HTMLParser):
    def __init__(self):
        super().__init__()
        self.stack = []
        self.errors = []
    def handle_starttag(self, tag, attrs):
        if tag not in ['br','hr','img','input','meta','link','area','base','col','embed','param','source','track','wbr']:
            self.stack.append(tag)
    def handle_endtag(self, tag):
        if tag not in ['br','hr','img','input','meta','link','area','base','col','embed','param','source','track','wbr']:
            if self.stack and self.stack[-1] == tag:
                self.stack.pop()
            else:
                self.errors.append(f'Mismatched: </{tag}>')

with open('/app/output/final_report.html') as f:
    content = f.read()
v = Validator()
v.feed(content)
if v.errors:
    print('Errors:', v.errors[:10])
else:
    print('HTML structure valid. Stack:', v.stack[:5])
print(f'Total chars: {len(content):,}')
"

